module github.com/harnaas/harnaas

// Keep this directive aligned with the Go version pinned in mise.toml.
go 1.26.5

// Package cli holds the harnaas command tree.
//
// The package is deliberately flat: command files are named
// <noun>_group.go for a group root and <noun>_<verb>.go for a leaf
// command, and a subpackage is extracted only when Go's import-cycle
// rule forces it. See CLAUDE.md for the conventions this layout carries.
package cli

// Command harnaas manages a project's AI-harness assets as a declared,
// versioned dependency of the repository.
package main

import (
	"fmt"
	"os"
)

// main is a placeholder so the module builds while the scaffolding lands.
// The process contract it owes — version loading, the cancellable root
// context, two-stage signal handling, the error switch and the exit-code
// mapping — replaces this body wholesale.
func main() {
	fmt.Fprintln(os.Stderr, "harnaas: no commands are wired up yet")
	os.Exit(1)
}

#!/bin/sh
#MISE description="Run every linter"
#MISE depends=["lint:go", "lint:gofmt", "lint:gomod", "lint:mise", "lint:shellcheck"]

#!/bin/sh
#MISE description="Check mise.toml for inline shell scripts that should be extracted"

set -eu

# Inline `run` blocks that grow past a couple of lines are unreviewable and
# unlintable by shellcheck. Anything longer belongs in mise-tasks/.
awk '
/^[ \t]*run = """/ || /^[ \t]*run = '\'''\'''\''/ {
    in_block = 1
    start_line = NR
    lines = 0
    next
}
in_block {
    if (/^[ \t]*"""/ || /^[ \t]*'\'''\'''\''/) {
        in_block = 0
        if (lines >= 3) {
            errors++
            printf "mise.toml:%d: multi-line script (%d lines) should be extracted to mise-tasks/\n", start_line, lines
        }
        next
    }
    lines++
}
END {
    if (errors > 0) {
        exit 1
    }
}
' mise.toml
